window.TEXTP["9.50"] = [{"n":1022,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":28.9,"mt":0.9,"pb":0.46,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Ахмад привёл сообщение от Ибн ‘Умара о том, что в отношении сока он сказал: <i>«Можешь пить его до тех пор, пока им не овладеет шайтан».</i> Его спросили: <i>«А через какое время им овладевает шайтан?».</i> Он ответил: <i>«Через три дня».</i>"],["p","Муслим (2004) и другие авторы сборников привели хадис от Ибн ‘Аббаса о том, что он замачивал для пророка (да благословит его Аллах и приветствует) изюм, и он пил эту настойку день, два и до вечера третьего дня, после чего повелевал прислуге либо допить его, либо вылить."],["p","Абу Дауд сказал, что смысл слов «поил им прислугу» означают, что он торопился напоить им, прежде чем он станет непригодным для питья."],["h","<b>• ВОПРОС № 7: В ТЕЧЕНИЕ КАКОГО ВРЕМЕНИ НАБИЗ ОСТАЁТСЯ БЕЗАЛКОГОЛЬНЫМ НАПИТКОМ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Предположительно, это срок, не превышающий трёх дней».</i>",{"mt":0.34}],["p","Исходя из вышеприведённого хадиса со слов Ибн ‘Аббаса."],["p","Муслим (2005) и другие авторы сборников привели хадис ‘Аиши о том, что по утрам она заготавливала набиз, а вечером на ужин пророк (да благословит его Аллах и приветствует) выпивал его. Если оставалось что-то, она выпивала его, либо выливала. Затем она с ночи заготавливала набиз, а утром пророк (да благословит его Аллах и приветствует) завтракал и выпивал его после завтрака. ‘Аиша сказала: <i>«И мы мыли посуду, в которой приготовляли набиз, по утрам и вечерам».</i>"],["p","Это не противоречит предыдущему хадису от Ибн ‘Аббаса, где говорилось, что пророк (да благословит его Аллах и приветствует) пил его день, два, и до вечера третьего дня, так как три дня охватывают больший срок, не отрицая при этом меньший. И оба этих хадиса приводятся в Сахихе у Муслима."],["h","<b>• ВОПРОС № 8: ЖЕЛАТЕЛЬНО ПИТЬ С ТРЕМЯ ПЕРЕДЫШКАМИ</b>",{"mt":0.32,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«Из этикета питья — питьё с тремя передышками».</i>",{"mt":0.34}]],"notes":[]},{"n":1023,"head":"КНИГА 14. НАПИТКИ","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Исходя из хадиса, приводимого в обоих Сахихах со слов Анаса о том, что пророк (да благословит его Аллах и приветствует) пил с тремя передышками<sup>18</sup>."],["p","В версии хадиса, приводимого у Муслима (2028–123), говорится: <i>«Пророк (да благословит его Аллах и приветствует) во время питья делал три передышки и говорил:</i> <b><i>«Поистине, это лучше утоляет жажду, и безопаснее и приятнее на вкус (или легче глотается)»»<sup>19</sup>.</i></b>"],["p","Под передышками в хадисах имеется в виду то, что он дышал между приёмами жидкости в сторону от сосуда."],["h","<b>• ВОПРОС № 9: НЕОБХОДИМО НЕ ДЫШАТЬ В СОСУД</b>",{"mt":0.3,"fr":1}],["p","А что касается того, чтобы дышать в сосуд, то это было запрещено исходя из хадиса, приводимого в обоих Сахихах и других сборниках со слов Абу Катады о том, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Когда кто-либо из вас пьёт, пусть не дышит в сосуд»<sup>20</sup>.</i></b>",{"mt":0.34}],["p","Ахмад, Абу Дауд, Ибн Маджа и ат-Тирмизи, подтвердивший его достоверность, привели хадис со слов Ибн ‘Аббаса о том, что пророк (да благословит его Аллах и приветствует) запретил дышать в сосуд или дуть в него<sup>21</sup>."],["p","Ахмад и ат-Тирмизи, подтвердивший его достоверность, привели хадис со слов Абу Са‘ида о том, что пророк (да благословит его Аллах и приветствует) запретил дуть в питьё и тогда один человек сказал: <i>«А что мне делать, если я вижу соринки?»,</i> — на что пророк (да благословит его Аллах и приветствует) ответил: <b><i>«Слей их».</i></b> Он сказал: <i>«Поистине, я не напиваюсь одним вздохом»</i> (то есть, не дыша в сосуд при питье). Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«В таком случае дыши, отдалив сосуд от своего рта»<sup>22</sup>.</i></b>"]],"notes":[[18,"Аль-Бухари (5631), Муслим (2028–122)."],[19,"В версии хадиса, приводимого Абу Даудом (3727) есть дополнение о том, что пророк (да благословит его Аллах и приветствует) к этому ещё добавил (<img src=\"img/pg-9/i24.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\"> ): <b><i>«…и легче для желудка».</i></b>"],[20,"Аль-Бухари (5630), Муслим (267: 63, 65, 121)."],[21,"Абу Дауд (3728), Ибн Маджа (3429). См. «аль-Ирва» (1977)."],[22,"Малик (2/925), ат-Тирмизи (1887), Ибн Хиббан (5327). См. «ас-Сильсиля с-сахиха» (385)."]]},{"n":1024,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","И этого же придерживаются обладатели знания."],["p","А что касается запрета дышать в сосуд, то это связано с опасением того, что часть слюны или соплей пьющего может выйти и смешаться с водой. Также может быть, что у некоторых во рту присутствует неприятный запах, который может передаться воде по причине её мягкости и нежности."],["p","Также в этом есть уподобление животным, которые лакают из посуды и дышат в неё же, пуская свои слюни, затем снова пьют из этой же посуды."],["p","Поэтому соблюдение данного этикета, дыша в сторону от сосуда, ближе к благонравию и благовоспитанности."],["p","Дуть в питьё может понадобиться для одного из двух: либо по причине его горячести, и тогда следует подождать, пока остынет, либо же по причине наличия на поверхности соринок, и тогда необходимо удалить пальцами или палочкой. Если же это представляется трудным, то пусть сольёт часть жидкости вместе с соринками, как об этом говорилось в ранее приводимом хадисе."],["h","<b>• ВОПРОС № 10: ПИТЬЁ ПРАВОЙ РУКОЙ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…и пить правой рукой…».</i>",{"mt":0.34}],["p","Исходя из того, что уже предшествовало в главе этикета принятия пищи в хадисе, который приводят Муслим и другие со слов Ибн ‘Умара о том, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Пусть никто из вас не ест и не пьёт левой рукой, ведь поистине это шайтан ест и пьёт левой рукой»<sup>23</sup>.</i></b>"],["h","<b>• ВОПРОС № 11: НЕОБХОДИМО ПИТЬ СИДЯ</b>",{"mt":0.31,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«…и пить сидя…».</i>",{"mt":0.34}],["p","Так как питьё сидя, относится к хорошим манерам и лучше для дыхания, утоления жажды и усвоения организмом жидкости."],["p","Также на это указывает хадис, который приводят Муслим и другие со слов Абу Са‘ида, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил пить стоя».</i>"]],"notes":[[23,"Муслим (2020), ат-Тирмизи (1800), Ахмад (2/23)."]]},{"n":1025,"head":"КНИГА 14. НАПИТКИ","side":"r","blocks":[["p","Также Муслим (2026–116) привёл хадис со слов Абу Хурайры о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Пусть никто из вас, ни в коем случае, не пьёт стоя. [А если он забыл и выпил, пусть вырвет]»<sup>24</sup>.</i></b>"],["p","И этому не противоречит хадис, который приводится в обоих Сахихах со слов Ибн ‘Аббаса, в котором говорится: <i>«Пророк (да благословит его Аллах и приветствует) выпил воду зам-зама стоя»<sup>25</sup>.</i>"],["p","Также, как и не противоречит хадис, который привели аль-Бухари (5615, 5616) и другие о том, что ‘Али выпил стоя, затем сказал: <i>«Люди считают порицаемым пить стоя, тогда как посланник Аллаха (да благословит его Аллах и приветствует) сделал то же, что сделал сейчас я».</i>"],["p","Также как и не противоречит хадис, который привели Ахмад, Ибн Маджа и ат-Тирмизи, подтвердивший его достоверность, со слов Ибн ‘Умара, который сказал: <i>«Во времена посланника Аллаха (да благословит его Аллах и приветствует) бывало так, что мы ели на ходу и пили стоя»<sup>26</sup>.</i>"],["p","Все эти хадисы можно объединить с хадисом о запрете таким образом, что под запретом имеется в виду нежелательность, даже если из слов: <b><i>«А если он забыл и выпил, пусть вырвет»</i></b> внешне понимается, что в отношении того, кто намеренно поступил вопреки Сунне, это будет запретным. Но даже в этом случае, нет противоречия, если исходить из науки основ фикха (усулю ль-фикх), так как его действие не противоречит его словам, обращённым лишь к общине, а в отношении слов, охватывающих как его самого, так и общину мусульман, его действие указывает на его исключительное положение в этом."],["p","И этого же придерживается большинство обладателей знания. Они считают, что запрет пророка (да благословит его Аллах и приветствует) относительно питья стоя, связан с этикетом и заботой о человеке, дабы он употреблял жидкость в спокойствии, что отдалит его от возможного причинения вреда его желудку, печени и т. п."]],"notes":[[24,"Шейх аль-Альбани сказал: <i>«В таком виде этот хадис является недостоверным. Достоверна лишь первая его половина. Подробно мы разобрали это в «ас-Сильсиля с-сахиха», стр. 175, и кто желает, может ознакомиться».</i> См. «ат-Та‘ликату р-радыййа» (3/97)."],[25,"Аль-Бухари (5617), Муслим (2027)."],[26,"Ахмад (5874), ат-Тирмизи (1880), Ибн Маджа (3301)."]]},{"n":1026,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":28.8,"mt":0.71,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","<b>• ВОПРОС № 12: ЖЕЛАТЕЛЬНО ПЕРЕДАВАТЬ СПРАВА ОТ СЕБЯ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…и отдать предпочтение в очерёдности тому, кто справа…».</i>",{"mt":0.34}],["p","Исходя из хадиса Анаса, приводимого в обоих Сахихах и других сборниках о том, что пророку (да благословит его Аллах и приветствует) послали молоко, разбавленное с водой в тот момент, когда справа от него сидел некий бедуин, а слева Абу Бакр. Пророк (да благословит его Аллах и приветствует) отпил из сосуда, затем передал его бедуину и сказал: <b><i>«Сначала тому, кто справа»<sup>27</sup>.</i></b>"],["p","В этих же источниках приводится хадис со слов Сахля ибн Са‘ида о том, что пророку (да благословит его Аллах и приветствует) отправили питьё, и он отпил из него. Справа от него в это время находился юноша, а слева находились старики. Тогда он обратился к юноше со словами: <b><i>«Ты позволишь мне сначала дать им?»,</i></b> — на что юноша ответил: <i>«О посланник Аллаха, клянусь Аллахом, я никому не уступлю своё право на тебя!»,</i> — и пророк (да благословит его Аллах и приветствует) передал сосуд ему в руки<sup>28</sup>."],["p","Уалию-Ллах ад-Дахляуи в «аль-Худжа аль-балига» говорит: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) хотел, тем самым, отрезать путь к соперничеству, ведь если бы Сунной являлось предпочтение того, кто лучше, то возможно они не были бы единогласны в отношении друг друга, кто из них лучше. Также возможно, что кто-то опечалился бы, если бы предпочтение отдали другому».</i>"],["h","<b>• ВОПРОС № 13: ТОТ, КТО ПОИТ ДРУГИХ, САМ ПЬЁТ ПОСЛЕДНИМ</b>",{"mt":0.3,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«…а тот, кто поит людей, пьёт последним…».</i>",{"mt":0.34}],["p","Исходя из хадиса, который привели Ибн Маджа, Абу Дауд и ат-Тирмизи, подтвердивший его достоверность. А аль-Мунзири в отношении него сказал, что все его передатчики являются надёжными. В хадисе со слов Абу Катады сообщается, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Тот, кто поит людей, пьёт последним»<sup>29</sup>.</i></b>"]],"notes":[[27,"Аль-Бухари (5612, 5619), Муслим (2029), Абу Дауд (3726)."],[28,"Малик (2/926), аль-Бухари (5620), Муслим (2030)."],[29,"Ахмад (19431), Абу Дауд (3725), ат-Тирмизи (1894), Ибн Маджа (3434)."]]},{"n":1027,"head":"КНИГА 14. НАПИТКИ","side":"r","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Также у Муслима приводится другая версия этого хадиса, в которой говорится, что Абу Катада сказал пророку (да благословит его Аллах и приветствует): <i>«Я не выпью, пока не выпьет посланник Аллаха»,</i> — на что пророк (да благословит его Аллах и приветствует) ответил: <b><i>«Поистине, тот, кто поит людей, пьёт последним»<sup>30</sup>.</i></b>"],["h","<b>• ВОПРОС № 14: ПОМИНАНИЕ ИМЕНИ АЛЛАХА ПЕРЕД ТЕМ, КАК ВЫПИТЬ, И ЕГО ВОСХВАЛЕНИЕ ПОСЛЕ ПИТЬЯ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…и произнести, «Бисми Ллях» в начале, а после сказать: «аль-Хамду ли-Ллях»…».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого ат-Тирмизи со слов Ибн ‘Аббаса о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Не пейте разом, подобно тому, как пьёт верблюд, однако пейте по два и по три глотка за раз, поминайте Аллаха при питье и восхваляйте Его, когда отрываетесь от сосуда»<sup>31</sup>.</i></b>"],["p","Ахмад, Абу Дауд, ат-Тирмизи, Ибн Маджа, ан-Насаи и аль-Бухари в «ат-Тарих» привели хадис со слов Абу Са‘ида, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) после того, как ел или пил, говорил:</i> <b><i>«Хвала Аллаху, Который накормил нас и напоил нас и сделал нас мусульманами»»<sup>32</sup>.</i></b>"],["h","<b>• ВОПРОС № 15: НЕЖЕЛАТЕЛЬНО ДЫШАТЬ В СОСУД ИЛИ ДУТЬ В НЕГО</b>",{"mt":0.31,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«Является нежелательным дышать в сосуд или дуть в него…».</i>",{"mt":0.34}],["p","Как уже было разобрано выше с приведением доводов в главе о запрете дышать в сосуд во время питья."],["p","[Сказал аш-Шаукани]: <i>«…а также пить с горлышка бурдюка…».</i>"]],"notes":[[30,"Муслим (681), ад-Дарими (2/122), Ибн Аби Шейба (8/231)."],[31,"Слабый хадис. См. «Да‘иф аль-Джами‘» (6233)."],[32,"Слабый хадис. См. «Да‘иф Сунан Аби Дауд» (829), «Да‘иф Ибн Маджа» (709)."]]},{"n":1028,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Так как при этом человек не может контролировать давление воды и может поперхнуться, что представляет опасность для его здоровья. Также при этом он не видит и не может контролировать попадание грязи и соринок ему в рот<sup>33</sup>."],["p","Доводом же на это является хадис, приводимый в обоих Сахихах со слов Абу Са‘ида, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил загибать горлышко бурдюка, чтобы выпить из него»<sup>34</sup>.</i>"],["p","В другой версии этого хадиса, приводимой в тех же источниках, говорится: <i>«Загибание горла заключается в том, чтобы перевернуть бурдюк и выпить из его горлышка».</i>"],["p","А в сборнике аль-Бухари (5628) сообщается, что Абу Хурайра сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил пить с горлышка бурдюка».</i>"],["p","В версии, которую привёл Ахмад, есть дополнение о том, что Айюб сказал: <i>«И также я узнал, что, когда некий мужчина пил с горлышка бурдюка, вышла змея».</i>"],["p","А ад-Дахляуи в «аль-Худжа аль-балига» добавил: <i>«И она проникла в его желудок».</i>"],["p","Также аль-Бухари (5629) и другие составители сборников привели хадис от Ибн ‘Аббаса, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил пить с горлышка бурдю-ка».</i>"]],"notes":[[33,"Шейх аль-Альбани сказал: <i>«Причиной этого может быть то, что приводится в Муснаде Ибн Аби Шейбы с достоверным иснадом от Абу Са‘ида, который сказал: «Однажды один человек выпил из бурдюка, и в его желудок проскользнула маленькая змея, а посланник Аллаха (да благословит его Аллах и приветствует) запретил пить напрямую с горла бурдюка». Хадис привёл аль-Исма’или, о чём упоминается в «аль-Фатх» (10/74). Однако причиной запрета может быть не только это. Так от ‘Аиши передаётся, что она сказала: «Пророк (да благословит его Аллах и приветствует) запретил пить с горлышка бурдюка, так как это приводит к появлению в нём неприятного запаха». Хадис передал аль-Хаким (4/140) и классифицировал его как достоверный, с чем согласился аз-Захаби, сказав: «Он соответствует условиям Муслима»».</i> См. «ат-Та‘ликату р-радыййа» (3/100)."],[34,"Аль-Бухари (5625, 5626), Муслим (2032), Абу Дауд (3720)."]]},{"n":1029,"head":"КНИГА 14. НАПИТКИ","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","И это не противоречит тому, что передали Ибн Маджа (3423) и ат-Тирмизи (1892) со слов Кабши, которая сказала: <i>«Однажды посланник Аллаха (да благословит его Аллах и приветствует) навестил нас и выпил стоя с горлышка висящего бурдюка. Тогда я встала и отрезала горлышко»<sup>35</sup>.</i>"],["p","Ахмад, Ибн Шахин, ат-Тирмизи в «аш-Шама’иль», ат-Табарани и ат-Тахави привели подобный хадис со слов Умм Суляйм<sup>36</sup>."],["p","Также подобный хадис привели Абу Дауд и ат-Тирмизи со слов ‘Абду-Ллаха ибн Бусра<sup>37</sup>."],["p","Своим действием пророк (да благословит его Аллах и приветствует) показал дозволенность этого, а хадисы с запретом указывают на нежелательность, а не на категоричный запрет этого."],["p","Возможно, он сделал это из-за наличия какой-то сложности поступить по-иному, и тогда хадисы о запрете касаются ситуации, в которой нет затруднения."],["p","О запрете утверждал Ибн Хазм, а от Ахмада передаётся, что он считал это положение отменённым."],["h","<b>• ВОПРОС № 16: ЖИДКОСТЬ, В КОТОРУЮ ПОПАЛА НЕЧИСТОТА</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Если нечистота попадёт в жидкость, её уже нельзя пить, но, если нечистота попадёт в твёрдую пищу, достаточно выкинуть нечистоту вместе с окружающей её пищей».</i>",{"mt":0.34}],["p","Исходя из хадиса, который привели аль-Бухари (235) и другие со слов Маймуны, которая сказала: <i>«Когда посланник Аллаха (да благословит его Аллах и приветствует) был спрошен о мыши, которая упала в жир и умерла в нём, он ответил:</i> <b><i>«Выбросьте её вместе с тем, что её окружает, и можете есть ваш жир»».</i></b>"],["p","Абу Дауд и ан-Насаи привели этот хадис со следующими дополнениями: <i>«Когда посланник Аллаха (да благословит его Аллах и приветствует</i>"]],"notes":[[35,"В сборнике «Сахих Ибн Маджа» (2780) говорится: <i>«И я отрезала горлышко бурдюка, желая благодати прикосновения к нему посланника Аллаха (да благословит его Аллах и приветствует)».</i>"],[36,"Слабый хадис. См. «ат-Та‘ликату р-радыййа» (3/101)."],[37,"Слабый хадис. См. «Да‘иф Сунан Аби Дауд» (797), «Да‘иф Сунан ат-Тирмизи» (321)."]]},{"n":1030,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","<i>) был спрошен о мыши, которая упала в жир, он ответил:</i> <b><i>«Если жир был твёрдым, то выбросьте мышь и то, что вокруг неё, если же он был жидким, то не приближайтесь к нему»»<sup>38</sup></i></b>. Достоверность хадиса подтвердил Ибн Хиббан."],["p","Ахмад (7177), Абу Дауд (3842) и ат-Тирмизи привели хадис от Абу Хурайры, который сказал: <i>«Когда посланник Аллаха (да благословит его Аллах и приветствует) был спрошен о мыши, которая упала в жир и умерла, он сказал:</i> <b><i>«Если он был твёрдым, извлеките мышь с тем, что её окружает, и ешьте оставшееся. Если же он был жидким, не приближайтесь к нему»»<sup>39</sup>.</i></b> Также этот хадис передал ан-Насаи."],["p","Всё, что подобно мыши со стороны её нечистоты и брезгливого отношения к ней, при попадании в жир или нечто подобное этому, имеет такое же положение, как и положение мыши."],["p","И таким же является мнение обладателей знания в отношении твёрдой пищи. Если же пища была жидкой, то она вся становится нечистой и запрещается её употребление по согласованному мнению учёных<sup>40</sup>. Но, в отличие от аш-Шафи‘и, Абу Ханифа дозволял продавать это."]],"notes":[[38,"Иснад хадиса достоверный, однако учёные по хадисам, признавая это, считали хадис слабым, объясняя это тем, что Ма‘мар допустил ошибку. Об этом говорили аль-Бухари, о чём сказано в «ат-Тамхид» (9/37), Ибн Хаджар, ат-Тирмизи, Ибн Таймия в «аль-Фатава» (21/525), аль-Альбани в «Да‘иф ан-Насаи» (4271) и другие. Поэтому от Ахмада передаётся, что он считал, что если в жидкость попадёт нечистота, то она не становится нечистотой, кроме как, если поменяет по причине этого цвет, вкус или запах. То же самое говорил и аль-Бухари и Ибн Нафи‘ из маликитов, а также это передаётся и от самого Малика. См. «ат-Та‘ликату р-радыййа» (3/102)."],[39,"Шу‘айб аль-Арнаут в «Тахриджу ль-Муснад» сказал: <i>«Матн (текст) хадиса является достоверным, а все его передатчики, являются передатчиками обоих Сахихов. Однако Ма‘мар ошибся в иснаде и передал хадис от Ибн Шихаба, от Ибн аль-Мусайиба, а тот — от Абу Хурайры».</i>"],[40,"Однако в этом вопросе нет единогласия, и помимо Абу Ханифы и аль-Бухари, так же считал Ибн Хазм, что если в жидкость попала нечистота, но при этом она не изменила её вкуса, цвета и запаха, то эта жидкость остаётся чистой. См. «аль-Мухалля» (1/142)."]]},{"n":1031,"head":"КНИГА 14. НАПИТКИ","side":"r","frames":[{"s":"a","h":46.9,"mt":0,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","<b>• ВОПРОС № 17: ЗАПРЕТ ИСПОЛЬЗОВАНИЯ ЗОЛОТОЙ И СЕРЕБРЯНОЙ ПОСУДЫ ДЛЯ ЕДЫ И ПИТЬЯ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«И запрещено есть и пить из золотой и серебряной посуды».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах и других сборниках со слов Хузайфы о том, что он слышал, как посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Не облачайтесь в шёлк и не одевайте шёлковую одежду, не ешьте и не пейте из золотой и серебряной посуды, ведь, поистине, она для неверных в этом мире и для вас в мире ином»<sup>41</sup>.</i></b>"],["p","В этих же источниках приводится хадис со слов Умм Салямы о том, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, у того, кто пьёт из серебряной посуды, в желудке будет журчать адский огонь»<sup>42</sup>.</i></b>"],["p","А в версии хадиса, приводимого Муслимом, говорится: <b><i>«Поистине, у того, кто ест или пьёт…»</i></b>, и до конца хадиса."],["p","Также Муслим (2065, 2066) привёл хадис от аль-Бара ибн ‘Азиба, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил нам пить из серебряной посуды и сказал, что тот, кто пьёт из неё в этом мире, лишится этого в мире ином».</i>"],["p","Также Ахмад и Ибн Маджа привели хадис со слов ‘Аиши похожий на хадис Умм Салямы."],["p","Журчание, о котором говорится в хадисе — это звук, попадающей в желудок воды. Таким же является мнение обладателей знания относительно посуды из золота."],["p","Аш-Шафи‘и дозволял использовать при нужде серебро для скрепления им поломанной посуды, исходя из хадиса Анаса о том, что когда чаша пророка (да благословит его Аллах и приветствует) поломалась, место разлома скрепили посредством серебряной цепочки<sup>43</sup>."]],"notes":[[41,"Аль-Бухари (5632, 5633), Муслим (2067)."],[42,"Аль-Бухари (5634), Муслим (2068)."],[43,"Аль-Бухари (5638)."]]},{"n":1032,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Мухиддин ибн Ибрахим ан-Нуххас в «Танбиху ль-Гафилин» сказал: <i>«К грехам также относится использование мужчинами и женщинами посуды из золота и серебра для принятия пищи, хранения кремов, сурьмы и тому подобного, о чём говорили Шамсуддин ибн аль-Кайим и другие. И нет разницы, большой является эта посуда, наподобие подноса, или же маленькой, как флакон для хранения сурьмы, палочка для её нанесения, игла и т. п.</i>"],["p","Так же как является запретным использование золотой и серебряной посуды для пищи, так же запретным является и использование их для других целей, как для мужчин, так и для женщин. Также запрещено и ювелиру изготавливать такую посуду. А если кому-то преподнесут еду в золотой или серебряной посуде, тогда как он будет не в состоянии высказать этому порицание, то он может взять эту еду и переложить в другую посуду или на лепёшку хлеба, или даже на левую руку, чтобы есть правой. Так как в этом случае он уже не является тем, кто ест из золотой и серебряной посуды. То же самое относится к тому, когда он пожелает использовать сурьму из серебряного флакона, пусть он пересыпет её куда-нибудь, а затем использует. А Аллаху это ведомо лучше»."],["p","Я считаю, нет запрета в использовании золота и серебра для чего-либо иного, помимо еды и питья, однако запрет связан лишь с тем, чтобы есть и пить из золотой и серебряной посуды. Если же кто-то считает запретным что-либо, помимо этого, у него это не примется, кроме как с приведением довода, так как в основе всё дозволено, и уйти с этой основы можно только при наличии довода, уводящего с него."],["p","А что касается украшений из этих металлов, то в отношении этого также нет довода на запрет, кроме доводов запрета золота для мужчин. А в отношении серебра нет никого запрета, более того, пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Используйте серебро и делайте с ним, что пожелаете»<sup>44</sup>.</i></b>"]],"notes":[[44,"Ахмад (2/334, 378), Абу Дауд (4236). Шейх Мухаммад Амин аш-Шанкыти считал неправильным использование данного хадиса для дозволения мужчинам украшаться серебром, так как до этих слов в самом хадисе приходит запрет на то, чтобы наряжать золотом женщин, а затем следует указание на использование серебра. И это было в тот период, когда золото было запрещено, как для мужчин, так и для женщин. Впоследствии пророк (да благословит его Аллах и приветствует) дозволил женщинам использовать золото и натуральный шёлк в любой форме, оставив запрет только в отношении мужчин. Что же касается мужчин, то многие учёные считали, что из серебра им дозволяется именно кольцо, а также украшать им свои мечи. См. «Адва’у ль-баян» (2/132–133)."]]},{"n":1033,"head":"КНИГА 14. НАПИТКИ","side":"r","blocks":[["p","Это вкратце, что необходимо знать об украшениях, подробно же эту тему раскрывает аш-Шаукани в некоторых своих основательных и прекрасных исследованиях, к которым вы всегда можете обратиться."]],"notes":[]},{"front":true,"blocks":[["f","Книга 15",{"a":"c","z":40,"mt":332.3}],["f","<b>ОДЕЯНИЯ</b>",{"a":"c","z":55,"mt":-6}],["img","",{"src":"img/pg-9-orn.webp","w":68,"h":27,"mt":1.59}]],"notes":[]},{"n":1037,"head":"КНИГА 15. ОДЕЯНИЯ","side":"r","frames":[{"s":"a","h":46.8,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":46.9,"mt":0.71,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","КНИГА 15. ОДЕЯНИЯ",{"z":1.43}],["h","<b>• ВОПРОС № 1: ОБЯЗАТЕЛЬНОСТЬ ПРИКРЫТИЯ НАГОТЫ, КАК НА ЛЮДЯХ, ТАК И В УЕДИНЕНИИ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Прикрытие наготы обязательно, как на людях, так и в уединении».</i>",{"mt":0.34}],["p","Исходя из хадиса, который привели Ахмад (20034), Абу Дауд (4017), Ибн Маджа (1920) и ат-Тирмизи (2794), назвавший его достоверным. Все они передали его от Хакима ибн Хизама со слов его отца о том, что он обратился к пророку (да благословит его Аллах и приветствует) со словами: <i>«О, посланник Аллаха, что из нашего тела нам следует прикрывать, а что можно оставить?».</i> Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Скрывай свою наготу от всех, кроме супруги и наложницы, принадлежащей тебе».</i></b> Он спросил: <i>«А если мне долгое время придётся находиться среди людей?».</i> Пророк (да благословит его Аллах и приветствует) ответил: <b><i>«Если ты можешь скрыть свою наготу, скрой её».</i></b> Он вновь спросил: <i>«А что, если один из нас находится в уединении?».</i> Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Аллах больше людей заслуживает того, чтобы Его стыдились»<sup>1</sup>.</i></b>"],["p","Относительно границ того, что необходимо скрывать, учёные разошлись во мнениях по причине наличия различающихся доводов, и автор (аш-Шаукани) подробно разобрал этот вопрос в «Шарху ль-Мунтака»<sup>2</sup>."],["h","<b>• ВОПРОС № 2: ПОЛОЖЕНИЕ ШЁЛКОВОЙ ОДЕЖДЫ ДЛЯ МУЖЧИН И ЖЕНЩИН</b>",{"mt":0.3,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«Мужчине не дозволяется надевать одежду, полностью состоящую из шёлка».</i>",{"mt":0.34}]],"notes":[[1,"Хороший хадис. См. «аль-Ирва» (1810). Шейх аль-Альбани сказал: <i>«Внешний смысл хадиса указывает на обязательность прикрытия наготы, даже будучи в одиночестве, однако это спорный вопрос среди учёных, так, например, шафи‘иты считали, что это указание на желательность, а не на обязательность».</i>"],[2,"Есть достоверный хадис от пророка (да благословит его Аллах и приветствует), что он сказал: <b><i>«То, что находится между пупком и коленями, является наготой».</i></b> См. «Сахих аль-Джами‘» (5583); «аль-Ирва» (271, 1803)."]]},{"n":1038,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Исходя из хадиса, который приводится в обоих Сахихах и других сборниках со слов ‘Умара о том, что он слышал, как посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Не надевайте шёлк, поистине, тот кто наденет его в этом мире, будет лишён его в мире вечном»<sup>3</sup></i></b>. В этих же сборниках приводится схожий хадис со слов Анаса."],["p","Также в обоих Сахихах и других сборниках приводится хадис со слов Ибн ‘Умара о том, что его отцу ‘Умару понравилась одежда из парчи<sup>4</sup> и он, принеся её пророку (да благословит его Аллах и приветствует), сказал: <i>«О посланник Аллаха, купи её, чтобы облачаться в неё в дни праздников и приёма делегаций»,</i> — на это посланник Аллаха (да благословит его Аллах и приветствует) ответил: <b><i>«Поистине, это является одеждой тех, у кого нет доли в будущей жизни»<sup>5</sup>.</i></b>"],["p","Ахмад (4/394), ан-Насаи (8/161) и ат-Тирмизи (1720), назвавший его достоверным, привели хадис со слов Абу Мусы о том, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Золото и шёлк были разрешены женщинам моей общины и запрещены мужчинам».</i></b> В иснаде этого хадиса Са‘ид ибн Аби Хинд передаёт от Абу Мусы, тогда как Абу Хатим говорил, что он не застал его. Ибн Хазм назвал хадис достоверным<sup>6</sup>."],["p","Также Ахмад (1/115), Абу Дауд (4057), ан-Насаи (8/160), Ибн Маджа (3595) и Ибн Хиббан (7/396) привели хадис со слов ‘Али, который сказал: <i>«Пророк (да благословит его Аллах и приветствует) взял шёлк и положил справа от себя, затем взял золото и положил слева от себя, после чего сказал:</i> <b><i>«Поистине, эти два являются запретными для мужчин из моей общины»».</i></b> В версии Ибн Маджи есть дополнение: <b><i>«…и дозволены для женщин».</i></b> Хадис является приемлемым «хасан»<sup>7</sup>. Схожий с этим хадис привёл также и аль-Байхакы (3/275) с приемлемым иснадом."]],"notes":[[3,"Аль-Бухари (5426), Муслим (2067)."],[4,"Парча — тяжёлая шёлковая ткань с узорами."],[5,"Аль-Бухари (886, 2612), Муслим (2068), Абу Дауд (4040)."],[6,"Хадис достоверный. См. «аль-Ирва» (277); Шу‘айб аль-Арнаут «Тахриджу ль-Муснад» (19503)."],[7,"Хадис достоверный. См. «Сахих Аби Дауд» (4057), ан-Навави в «аль-Маджму‘» (4/140)."]]},{"n":1039,"head":"КНИГА 15. ОДЕЯНИЯ","side":"r","frames":[{"s":"a","h":46.8,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Также подобный хадис, в иснаде которого присутствует Кайс ибн Аби Хазим, привёл аль-Баззар со слов ‘Амра ибн Джарира аль-Баджали<sup>8</sup>."],["p","По данной теме есть и другие хадисы."],["p","Аль-Махди в «аль-Бахр» говорит, что существует единогласное мнение учёных о запрете шёлка для мужчин, несмотря на несогласие Ибн ‘Уляйи, так как единогласное мнение сформировалось уже после него."],["p","Однако аль-Кады аль-‘Ияд говорил<sup>9</sup>: <i>«Поистине, от некоторых предшественников передаётся, что они считали шёлк для мужчин дозволенным».</i> А Абу Дауд сказал: <i>«Шёлк носили около двадцати сподвижников».</i>"],["h","<b>• ВОПРОС № 3: РАЗНОГЛАСИЯ ОТНОСИТЕЛЬНО ШЁЛКОВЫХ ВСТАВОК В ОДЕЖДЕ</b>",{"mt":0.3,"fr":1}],["p","Учёные разошлись во мнениях относительно одежды, часть которой из шёлка, а часть из другой материи.",{"mt":0.34}],["p","Те, которые запрещали её, приводили в довод запрет пророка (да благословит его Аллах и приветствует) на ношение одежды, частично состоящей из шёлка, как это приводится в обоих Сахихах<sup>10</sup>"],["q","со слов ‘Али. Однако учёные по-разному объясняли использованное в хадисе слово ( ). Одни сказали, что это шёлковая одежда с на-"],["p","<img src=\"img/pg-9/i25.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\">",{"mt":-1.03}],["q","личием в ней вставок из других ниток. Другие учёные сказали, что речь идёт о разноцветной одежде. Однако оба этих объяснения не указывают на запрет одежды, часть которой из шёлка, а другая — из другого материала. Также учёными было высказано мнение, что под этим словом в хадисе подразумевался чистый шёлк без примеси других материалов.",{"mt":-0.26}],["p","Другая группа учёных, которые не считают запретным шёлк с примешанным к нему другим материалом, а считают запретным лишь чистый шёлк, аргументируют своё мнение хадисами наподобие того, который приводится у Ахмада (1879) и Абу Дауда (4055) со слов"]],"notes":[[8,"См. «аль-Бахру з-заххар» (2/467)"],[9,"См. «аль-Икмаль» (6/571)."],[10,"Хадис приводится со слов ‘Абду-Ллаха ибн ‘Умара. Аль-Бухари (2612, 6081); Муслим (2068, 2069)."]]},{"n":1040,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","Ибн ‘Аббаса, который сказал: <i>«Поистине, посланник Аллаха (да благословит его Аллах и приветствует) запретил шёлковую одежду».</i> В иснаде этого хадиса присутствует Хусайф ибн ‘Абду р-Рахман, который является слабым передатчиком<sup>11</sup>."],["p","А что касается пришедшего в хадисе слова (<img src=\"img/pg-9/i26.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\">), то имеется в виду одежда, которая полностью состоит из шёлка, без примеси хлопка или чего-либо иного. Дальнейший же разбор этого разногласия может сильно затянуться."],["p","Вопрос запрета шёлка с примесью другого материала является предметом большого спора среди учёных."],["p","Автор (аш-Шаукани) в «Хашияту ш-Шифа» говорит: <i>«Этот вопрос мы неоднократно разбирали с моим учителем, абсолютным муджтахидом, Саййидом ‘Абду ль-Кадиром ибн Ахмадом аль-Каукабани — да смилуется над ним Аллах — в дни, когда я читал ему. В итоге весь этот разбор достиг семи посланий, которые я впоследствии сократил и привёл в «Шарху ль-Мунтака», и желающий может обратиться к нему».</i>"],["p","В итоге он пришёл к запретности такой одежды, с чем вы можете ознакомиться, обратившись к труду «Хидаяту с-саиль иля адилляти ль-масаиль»."],["p","Уалию-Ллах ад-Дахляуи в «аль-Мусаува шарх аль-Муватта» говорит: <i>«Одежда, именуемая как «ас-сияра» — это та, в которой есть вставки из лёгкого шёлка или же большая часть которой состоит из шёлка. А «аль-кассий» — это также одежда с полосками из шёлка наподобие рёбер. Было сказано, что название одежда берёт от деревни Касс, располагающейся на берегу моря, либо Казз, но впоследствии буква «З» была заменена на «С». Учёные разделяют мнение о том, что шёлк запретен для мужчин и дозволен для женщин. Исключение они сделали для его незначительного количества в одежде, равного от одного до четырёх пальцев. Также некоторые учёные дозволяли ношение шёлковой одежды больному чесоткой или педикулёзом».</i>"],["p","Также в сборнике у Малика приводится, что ‘Али сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил надевать «аль-кассий»»<sup>12</sup>.</i>"]],"notes":[[11,"Достоверность хадиса подтвердили Ахмад Шакир в «Муснад Ахмад» (3/267); аль-Альбани в «ат-Та‘ликату р-радыййа» (3/112); Шу‘айб аль-Арнаут в «Тахриджу ль-Муснад» (3/371)."],[12,"Муслим (2078), Абу Дауд (4044), ат-Тирмизи (264)."]]},{"n":1041,"head":"КНИГА 15. ОДЕЯНИЯ","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","И этого мнения придерживаются обладатели знания."],["p","Юсуф ибн Ибрахим аль-Ардабили в «аль-Ануар ли а‘мали ль-абрар» сказал: <i>«А также дозволено надевать шёлковую одежду при крайней необходимости, как внезапное сражение, сильная жара или холод; а также при необходимости, как при чесотке и педикулёзе, будь то в пути или дома. И дозволяется ношение даже дорогой одежды из льна, хлопка, шерсти и шёлка».</i>"],["h","<b>• ВОПРОС № 4: ДОЗВОЛЕННОЕ КОЛИЧЕСТВО ШЁЛКА В ОДЕЖДЕ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Мужчине не дозволяется надевать чистый шёлк, количество которого в одежде превышает четыре пальца».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах со слов ‘Умара, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил одежду из шёлка, кроме как если в ней его будет вот столько: и показал нам соединённые вместе указательный и средний пальцы руки»<sup>13</sup>.</i>"],["p","В версии хадиса, приводимого у Муслима, говорится: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил нам шёлк, за исключением количества в два, три или четыре пальца»<sup>14</sup>.</i>"],["p","Уалию-Ллах ад-Дахляуи в «аль-Худжа аль-балига» говорит: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил надевать шёлк, парчу и такие виды шёлковой одежды, как «аль-кассий», «аль-маясир» и «аль-урджуан». При этом было дозволено одевать одежду, если количество, использованного в ней шёлка, не превышало места двух-трёх пальцев, так как такое количество несущественно в одежде и возможно, в его применении была некая нужда».</i>"],["h","<b>• ВОПРОС № 5: ДОЗВОЛЕНО НАДЕВАТЬ ШЁЛК В ЛЕЧЕБНЫХ ЦЕЛЯХ</b>",{"mt":0.3,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«Исключением является ношение шёлковой одежды для больного».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах и других сборниках со слов Анаса о том, что он сказал: <i>«Пророк (да благословит его Аллах и приветствует) дозволил ‘Абду р-Рахману ибн ‘Ауфу, а также</i>"]],"notes":[[13,"Аль-Бухари (5828, 5834); Муслим (2069)."],[14,"Муслим (2069–15), Абу Дауд (4042), ат-Тирмизи (1721)."]]},{"n":1042,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c","<i>аз-Зубайру надеть шёлковую одежду по причине того, что они болели чесоткой»<sup>15</sup>.</i>"],["p","Уалию-Ллах ад-Дахляуи в «аль-Худжа аль-балига» говорит: <i>«Так как в этом случае облачение в шёлк не преследуется желанием роскоши, однако делается с целью излечения».</i>"],["h","<b>• ВОПРОС № 6: ЗАПРЕТ СИДЕТЬ НА ШЁЛКОВЫХ ПОКРЫВАЛАХ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Также запрещено использовать шёлк в виде подстилок».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого у аль-Бухари со слов Хузайфы, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил нам есть и пить из золотой и серебряной посуды, а также он запретил нам одевать шёлк и парчу и сидеть на них. И он сказал:</i> <b><i>«Это для них (неверных) в этом мире, а для нас в мире вечном»»<sup>16</sup>.</i></b>"],["p","Есть и другие хадисы с таким смыслом, но данный хадис является прямым и недвусмысленным доводом в данном вопросе."],["p","Что же касается сравнения по аналогии с дозволенностью использования в виде покрывал материи, содержащей изображения, то это из области применения аналогии при наличии священного текста, что делает приведение аналогии недействительным."],["p","Ибн аль-Кайим сказал: «Даже если бы не было прямого текста, то наличие запрета на ношение шёлка также означало бы и запрет использования его в виде подстилок, подобно тому, как этот запрет включает в себя и запрет оборачивания в него. Всё это входит под понятие одеяния, как со стороны языка, так и со стороны Шариата, как об этом можно судить из слов Анаса, сказавшего: «И я направился и взял нашу циновку, которая почернела по причине долгого использования». Дословно: (<img src=\"img/pg-9/i27.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\">) «по причине долгого одевания»<sup>17</sup>."],["p","Но даже если бы это слово (<img src=\"img/pg-9/i28.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\">) не имело обобщающего значения, включающего, в том числе запрет использования шёлка в виде подстилки"]],"notes":[[15,"Аль-Бухари (2921, 2922), Муслим (2076), Абу Дауд (4056)."],[16,"Аль-Бухари (5837), Муслим (2067)."],[17,"Аль-Бухари (380), Муслим (658)."]]},{"n":1043,"head":"КНИГА 15. ОДЕЯНИЯ","side":"r","blocks":[["c",", то на запрет указывала бы правильная аналогия из области идентичности (<img src=\"img/pg-9/i29.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\">), либо из области, называемой «тем более» (<img src=\"img/pg-9/i30.webp\" alt=\"\" style=\"height:1.5em;vertical-align:-0.5em;margin:-.3em 0\">)."],["p","В итоге мы имеем то, что на запрет использования шёлка в виде подстилки указывают: прямой текст, общий смысл понятия «одеяние», а также правильная аналогия."],["p","И не дозволено отвергать всё это, опираясь на неоднозначный смысл, извлекаемый из слов Всевышнего Аллаха: <b>«И Он создал для вас всё, что на земле»<sup>18</sup>.</b>"],["p","Также, исходя из аналогии, запрет, по более правильному мнению, должен распространяться и на шёлк, находящийся на внутренней, а не на внешней стороне подстилки. По другому мнению, в отношении шёлковых подстилок запретным является непосредственное соприкосновение с шёлком. Если исходить из приемлемости отличий между ними, то аналогия станет неприемлемой (так как сравнение по аналогии происходит лишь между схожими вещами). Если же отличие не установлено, тогда нет необходимости в дополнительном постановлении (так как запрет объемлет и то и другое)."],["p","Некоторые из числа учёных правоведов, исходя из обобщённого запрета использования шёлковых подстилок, запрещали его как для мужчин, так и для женщин. Этого мнения придерживались жители Хорасана из числа шафи‘итов. Другая группа учёных, наоборот, считала их использование мужчинами и женщинами дозволенным. Истиной же в данном вопросе является разграничение, и кому дозволено одевать шёлк, тем дозволено и использование шёлковых подстилок, а для кого запрещена одежда из шёлка, тем запрещено и сидеть на нём. И это мнение принадлежит большинству учёных, а также шафи‘итам, проживающим в Ираке»<sup>19</sup>."],["p","Мухиддин ад-Димашкы в «Танбиху ль-гафилин» сказал: <i>«Сидение на шёлковом и облачение в него является запретным для мужчин».</i>"],["p","Ар-Рафи‘и считал запретным сидеть на шёлке также и для женщин, а ан-Навави дозволял это."]],"notes":[[18,"Сура «аль-Бакара», аят 29."],[19,"См. «И‘ляму ль-муваккы’ин» (4/203)."]]}];
